where del_flag = 0

    and (order_no like concat('%', #{keyword}, '%')
    or customer_name like concat('%', #{keyword}, '%')
    or product_name like concat('%', #{keyword}, '%')
    or owner like concat('%', #{keyword}, '%'))


    and status = #{status}


    and pay_status = #{payStatus}


    and customer_id = #{customerId}

